"""Portable checks for the script generated by the macOS installer."""

import contextlib
import io
import json
import plistlib
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

from webapp import __version__
from webapp.install_desktop import launcher_script, main


@unittest.skipUnless(shutil.which("zsh"), "macOS command launchers require zsh")
class CommandLauncherTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name) / "Research workspace"
        (self.root / "webapp").mkdir(parents=True)
        source = Path(__file__).resolve().parents[2]
        for relative in ("启动 TradingAgents.command", "webapp/launch.command"):
            shutil.copyfile(source / relative, self.root / relative)
            (self.root / relative).chmod(0o755)

    def python(self, script):
        executable = self.root / ".venv/bin/python"
        executable.parent.mkdir(parents=True)
        executable.write_text("#!/bin/sh\n" + script, encoding="utf-8")
        executable.chmod(0o755)

    def launch(self, relative, *args):
        return subprocess.run(
            ["zsh", str(self.root / relative), *args], cwd=self.tmp.name,
            input="", capture_output=True, text=True, timeout=5,
        )

    def test_both_commands_open_web_and_forward_arguments_from_any_directory(self):
        self.python('pwd\nprintf "%s\\n" "$@"\n')
        for relative in ("启动 TradingAgents.command", "webapp/launch.command"):
            with self.subTest(relative=relative):
                result = self.launch(relative, "--port", "18780")
                self.assertEqual(result.returncode, 0, result.stderr)
                self.assertEqual(result.stdout.splitlines(), [
                    str(self.root.resolve()), "-m", "webapp.server", "--open", "--port", "18780",
                ])

    def test_missing_environment_explains_how_to_install(self):
        result = self.launch("启动 TradingAgents.command")
        self.assertEqual(result.returncode, 1)
        self.assertIn("python3.13 -m venv .venv", result.stderr)
        self.assertIn("pip install -e .", result.stderr)

    def test_server_failure_keeps_exit_status_without_waiting_on_non_terminal(self):
        self.python('echo "offline server failure" >&2\nexit 7\n')
        result = self.launch("webapp/launch.command")
        self.assertEqual(result.returncode, 7)
        self.assertIn("offline server failure", result.stderr)


class DesktopInstallerTests(unittest.TestCase):
    def test_generated_app_uses_workspace_version(self):
        def compile_app(command, **kwargs):
            if command[0] == "osacompile":
                app = Path(command[command.index("-o") + 1])
                (app / "Contents/Resources").mkdir(parents=True)
                (app / "Contents/Info.plist").write_bytes(plistlib.dumps({}))

        with tempfile.TemporaryDirectory() as directory:
            home = Path(directory)
            (home / "Desktop").mkdir()
            with (
                patch("webapp.install_desktop.sys.platform", "darwin"),
                patch("webapp.install_desktop.Path.home", return_value=home),
                patch("webapp.install_desktop.subprocess.run", side_effect=compile_app),
                contextlib.redirect_stdout(io.StringIO()),
            ):
                main()
            info = plistlib.loads(
                (home / "Desktop/TradingAgents 投研台.app/Contents/Info.plist").read_bytes()
            )
            self.assertEqual(info["CFBundleShortVersionString"], __version__)
            self.assertEqual(info["CFBundleIdentifier"], "local.tradingagents.workspace")

    def test_quotes_paths_and_detaches_stdin_stdout_stderr(self):
        script = launcher_script(
            Path("/tmp/Alan's research"), "/tmp/My Python/bin/python", Path("/tmp/Local Data")
        )
        self.assertIn("/bin/sh -c", script)
        self.assertIn("webapp.server --port 18765 --open", script)
        command = json.loads(script.split("do shell script ", 1)[1].split("\nend run", 1)[0])
        self.assertIn("2>&1 < /dev/null &", command)
        self.assertTrue(command.endswith("> /dev/null 2>&1 < /dev/null"))
        self.assertIn("My Python", command)

    def test_non_macos_returns_actionable_error(self):
        with (
            patch("webapp.install_desktop.sys.platform", "linux"),
            self.assertRaisesRegex(SystemExit, "tradingagents-web --open"),
        ):
            main()
